const shellScript = `
const wlToken=localStorage.getItem('wl_token');
let wlStoredUser=null;
try{wlStoredUser=JSON.parse(localStorage.getItem('wl_user')||'null')}catch(_error){localStorage.removeItem('wl_user')}
const wlAuthActions=document.querySelector('#wl-auth-actions');
const wlRoleHome={BUYER:'/acheteur',PRODUCER:'/producteur',ADMIN:'/admin'};
const wlEscape=(value)=>String(value??'').replace(/[&<>\"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#039;'}[character]));
const wlLogout=()=>{localStorage.removeItem('wl_token');localStorage.removeItem('wl_user');location.href='/'};
const wlProductImageMap=[
  {terms:['haricot blanc du koki','haricot blanc'],src:'/assets/products/haricot-blanc-du-koki.jpg',alt:'Haricots blancs du Koki'},
  {terms:['haricot rouge'],src:'/assets/products/haricot-rouge.jpg',alt:'Haricots rouges locaux'},
  {terms:['haricot noir'],src:'/assets/products/haricot-noir.jpg',alt:'Haricots noirs locaux'},
  {terms:['huile de palme'],src:'/assets/products/huile-de-palme.jpg',alt:'Huile de palme locale'},
  {terms:['jus de folere'],src:'/assets/products/jus-de-folere.jpg',alt:'Jus de foléré local'},
  {terms:['riz de yagoua','riz yagoua'],src:'/assets/products/riz-de-yagoua.jpg',alt:'Riz de Yagoua'},
  {terms:['folere'],src:'/assets/products/folere-legume.jpg',alt:'Foléré frais'},
  {terms:['arachide'],src:'/assets/products/arachide.jpg',alt:'Arachides locales'},
  {terms:['cacao'],src:'/assets/products/cacao.jpg',alt:'Cacao local'},
  {terms:['cafe'],src:'/assets/products/cafe.jpg',alt:'Café local'},
  {terms:['mais'],src:'/assets/products/mais.png',alt:'Grains de maïs jaune'},
  {terms:['miel'],src:'/assets/products/miel.jpg',alt:'Miel local'},
  {terms:['moringa'],src:'/assets/products/moringa.jpg',alt:'Moringa local'},
  {terms:['neem'],src:'/assets/products/neem.jpg',alt:'Neem local'},
  {terms:['okok'],src:'/assets/products/okok.jpg',alt:'Okok local'},
  {terms:['soja'],src:'/assets/products/soja.jpg',alt:'Graines de soja locales'},
  {terms:['tasba'],src:'/assets/products/tasba.jpg',alt:'Tasba local'}
 ];
const wlNormalizeProduct=(value)=>String(value??'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().trim();
const wlImageForProduct=(title)=>{const normalized=wlNormalizeProduct(title);return wlProductImageMap.find((entry)=>entry.terms.some((term)=>normalized.includes(wlNormalizeProduct(term))))};
const wlProductImageData=new Map();
const wlSafeImageSource=(value)=>{if(!value)return null;try{const url=new URL(String(value),location.origin);if(url.origin===location.origin||url.protocol==='https:')return url.href}catch(_error){}return null};
const wlRegisterProductImages=(products)=>{(products||[]).forEach((product)=>{const title=wlNormalizeProduct(product?.title);if(title&&product?.imageUrl)wlProductImageData.set(title,product.imageUrl)});document.querySelectorAll('.wl-product-photo').forEach((photo)=>{const source=wlProductImageData.get(wlNormalizeProduct(photo.textContent));if(source){photo.dataset.imageUrl=source;photo.removeAttribute('data-wl-photo-ready')}});wlEnhanceProductPhotos()};
const wlEnhanceProductPhotos=()=>{document.querySelectorAll('.wl-product-photo:not([data-wl-photo-ready])').forEach((photo)=>{photo.dataset.wlPhotoReady='true';const fallback=wlImageForProduct(photo.textContent);const direct=wlSafeImageSource(photo.dataset.imageUrl||wlProductImageData.get(wlNormalizeProduct(photo.textContent)));const product=direct?{src:direct,alt:photo.textContent.trim()}:fallback;if(!product)return;const image=document.createElement('img');image.src=product.src;image.alt=product.alt;image.loading='lazy';image.decoding='async';const label=document.createElement('span');label.className='wl-product-photo-label';label.textContent=photo.textContent.trim();photo.classList.add('wl-has-image');photo.replaceChildren(image,label)})};
const wlPhotoObserver=new MutationObserver(()=>wlEnhanceProductPhotos());wlPhotoObserver.observe(document.body,{childList:true,subtree:true});wlEnhanceProductPhotos();
function wlRenderAuth(user){
  if(!wlAuthActions||!user)return;
  wlAuthActions.innerHTML='<a class="wl-btn" href="'+wlRoleHome[user.role]+'">Mon espace</a><a class="wl-btn" href="/notifications">Notifications <span id="wl-notification-count" class="wl-pill" style="padding:3px 6px;margin-left:3px">0</span></a><button class="wl-btn primary" type="button" id="wl-shell-logout">Quitter</button>';
  document.querySelector('#wl-shell-logout')?.addEventListener('click',wlLogout);
}
async function wlRefreshNotifications(){
  if(!wlToken)return;
  try{
    const response=await fetch('/api/notifications?unreadOnly=true',{headers:{Authorization:'Bearer '+wlToken}});
    if(response.status===401){wlLogout();return;}
    if(!response.ok)return;
    const data=await response.json();
    const badge=document.querySelector('#wl-notification-count');
    if(badge){badge.textContent=String(data.unreadCount||0);badge.hidden=!data.unreadCount;}
  }catch(_error){/* Le contenu principal reste disponible hors connexion. */}
}
async function wlValidateSession(){
  if(!wlToken||!wlStoredUser)return null;
  try{
    const response=await fetch('/api/me',{headers:{Authorization:'Bearer '+wlToken}});
    if(!response.ok)throw new Error('session-expired');
    const data=await response.json();
    localStorage.setItem('wl_user',JSON.stringify(data.user));
    wlRenderAuth(data.user);
    wlRefreshNotifications();
    window.setInterval(wlRefreshNotifications,20000);
    return data.user;
  }catch(_error){wlLogout();return null;}
}
wlValidateSession();
`;

function layout(title: string, content: string, script = '', active = '') {
  const pageContent = active === 'catalogue' ? content.replace('</main>', `${catalogueShowcase}</main>`) : content;
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} · Weli-Link Market</title><style>${styles}${productImageStyles}${productImageFallbackStyles}${productUploadStyles}${cartStyles}${dashboardStyles}</style></head><body><div class="wl-shell">${header(active)}${pageContent}</div><script>${shellScript}${script}</script></body></html>`;
}

const authScript = `
const form=document.querySelector('#auth-form');
const message=document.querySelector('#auth-message');
const isRegister=form.dataset.mode==='register';
form.addEventListener('submit',async(e)=>{e.preventDefault();message.textContent='Connexion en cours…';message.className='wl-alert';const values=Object.fromEntries(new FormData(form).entries());const body=isRegister?values:{identifier:values.identifier,password:values.password};if(isRegister&&!body.email)delete body.email;try{const res=await fetch(isRegister?'/api/auth/register':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw new Error(data.error?.message||'Une erreur est survenue.');localStorage.setItem('wl_token',data.token);localStorage.setItem('wl_user',JSON.stringify(data.user));const next=new URLSearchParams(location.search).get('next');if(next&&next.startsWith('/')){location.href=next}else{location.href=data.user.role==='PRODUCER'?'/producteur':data.user.role==='ADMIN'?'/admin':'/acheteur'}}catch(error){message.textContent=error.message;message.className='wl-alert error'}});
`;

export function renderAuthPage(mode: 'login' | 'register') {
  const register = mode === 'register';
  const content = `<main class="wl-auth"><section class="wl-auth-card"><p class="wl-kicker">${register ? 'Rejoindre Weli-Link' : 'Accès sécurisé'}</p><h1 class="wl-title">${register ? 'Créez votre espace.' : 'Bienvenue sur Weli-Link.'}</h1><p class="wl-subtitle">${register ? 'Choisissez votre rôle pour accéder à un espace adapté à vos actions.' : 'Connectez-vous pour acheter, publier une offre ou gérer vos demandes.'}</p><form id="auth-form" class="wl-form" data-mode="${mode}" style="margin-top:23px">${register ? '<div class="wl-field"><label>Nom complet</label><input name="name" required minlength="2" placeholder="Amina Douala"></div>' : ''}${register ? '<div class="wl-field"><label>Vous êtes</label><select name="role"><option value="BUYER">Acheteur</option><option value="PRODUCER">Producteur</option></select></div>' : ''}<div class="wl-field"><label>${register ? 'Téléphone' : 'Téléphone ou e-mail'}</label><input name="${register ? 'phone' : 'identifier'}" required placeholder="+237 690 000 001"></div>${register ? '<div class="wl-field"><label>E-mail (facultatif)</label><input name="email" type="email" placeholder="vous@exemple.com"></div>' : ''}<div class="wl-field"><label>Mot de passe</label><input name="password" type="password" required minlength="8" placeholder="Au moins 8 caractères"></div><div id="auth-message" class="wl-alert" hidden></div><div class="wl-form-actions"><button class="wl-btn primary" type="submit">${register ? 'Créer mon compte' : 'Se connecter'}</button></div></form><div class="wl-auth-footer">${register ? 'Vous avez déjà un compte ? <a href="/connexion">Se connecter</a>' : 'Vous n’avez pas encore de compte ? <a href="/inscription">Créer un compte</a>'}<br><a href="/">← Retour à l’accueil</a></div></section></main>`;
  const script = authScript.replace("message.textContent='Connexion en cours…'", "message.hidden=false;message.textContent='Connexion en cours…'");
  return layout(register ? 'Créer un compte' : 'Se connecter', content, script);
}

const protectedGuard = `
const token=localStorage.getItem('wl_token');if(!token){location.href='/connexion?next='+encodeURIComponent(location.pathname)}
let user=null;try{user=JSON.parse(localStorage.getItem('wl_user')||'null')}catch(_error){localStorage.removeItem('wl_user')}const logout=()=>{localStorage.removeItem('wl_token');localStorage.removeItem('wl_user');location.href='/'};document.querySelectorAll('[data-logout]').forEach((button)=>button.addEventListener('click',logout));if(token){fetch('/api/me',{headers:{Authorization:'Bearer '+token}}).then((response)=>{if(!response.ok)logout();return response.json()}).then((data)=>{if(data?.user){user=data.user;localStorage.setItem('wl_user',JSON.stringify(user))}}).catch(()=>logout())}
`;

export function renderCataloguePage() {
  const content = `<main class="wl-page"><section class="wl-intro"><div><p class="wl-kicker">Le catalogue Weli-Link</p><h1 class="wl-title">Trouvez ce qui vous rapproche.</h1><p class="wl-subtitle">Consultez les offres publiées par les producteurs. Pour envoyer une demande, connectez-vous ou créez un compte acheteur.</p></div><div class="wl-intro-actions"><a class="wl-btn primary" href="/connexion?next=/acheteur">Demander un produit</a><a class="wl-btn" href="/assistant">Parler à Weli</a></div></section><section class="wl-card"><div class="wl-field"><label>Rechercher dans le catalogue</label><input id="catalogue-search" placeholder="Maïs, miel, beurre de karité…"></div></section><section class="wl-section"><div id="catalogue-list" class="wl-grid"><div class="wl-empty">Chargement des offres…</div></div></section></main><footer class="wl-footer">Weli-Link Market · <a href="/">Accueil</a><a href="/connexion">Connexion</a></footer>`;
  const script = `
const list=document.querySelector('#catalogue-list');const search=document.querySelector('#catalogue-search');let products=[];const esc=(v)=>String(v??'').replace(/[&<>\"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[c]));const money=(v)=>new Intl.NumberFormat('fr-FR').format(v)+' F';function render(){const q=search.value.toLowerCase().trim();const filtered=products.filter(p=>(p.title+' '+p.category+' '+p.location).toLowerCase().includes(q));list.innerHTML=filtered.length?filtered.map(p=>'<article class="wl-card wl-product"><div class="wl-product-photo">'+esc(p.title)+'</div><div><h3><a class="wl-product-title" href="/produit/'+encodeURIComponent(p.id)+'">'+esc(p.title)+'</a></h3><p>'+esc(p.location)+' · '+esc(p.unit)+'</p><span class="wl-status">'+(p.availability.state==='LOW_STOCK'?'Stock faible':'Disponible')+'</span></div><div class="wl-product-meta"><span class="wl-price">'+money(p.priceXaf)+'</span><a class="wl-btn accent" href="/commande?productId='+encodeURIComponent(p.id)+'">Commander</a></div></article>').join(''):'<div class="wl-empty">Aucune offre ne correspond à votre recherche.</div>';wlRegisterProductImages(filtered)}async function load(){try{const res=await fetch('/api/products');const data=await res.json();products=data.products||[];wlRegisterProductImages(products);render()}catch(error){list.innerHTML='<div class="wl-alert error">Impossible de charger le catalogue.</div>'}}search.addEventListener('input',render);load();
`;
  return layout('Catalogue', content, script, 'catalogue');
}

export function renderProductDetailPage() {
  const content = `<main class="wl-page"><a class="wl-back-link" href="/catalogue">← Retour au catalogue</a><section id="product-detail" class="wl-product-detail"><div class="wl-empty">Chargement de la fiche produit…</div></section></main><footer class="wl-footer">Weli-Link Market · Fiche produit</footer>`;
  const script = `
const root=document.querySelector('#product-detail');const productId=decodeURIComponent(location.pathname.split('/').filter(Boolean).pop()||'');const money=(value)=>new Intl.NumberFormat('fr-FR').format(value)+' F';const statusLabel={AVAILABLE:'Disponible',LOW_STOCK:'Stock faible',CHECK_REQUIRED:'À reconfirmer',OUT_OF_STOCK:'Rupture',PAUSED:'Suspendue'};const safeImage=(value)=>{if(!value)return null;try{const url=new URL(value,location.origin);if(url.origin===location.origin||url.protocol==='https:')return url.href}catch(_error){}return null};function text(value){return String(value??'')}function render(product){root.replaceChildren();const media=document.createElement('div');media.className='wl-product-detail-media';const source=safeImage(product.imageUrl);if(source){const image=document.createElement('img');image.src=source;image.alt=product.title;image.loading='eager';media.appendChild(image)}else{media.textContent=product.title}const copy=document.createElement('div');copy.className='wl-product-detail-copy';const kicker=document.createElement('p');kicker.className='wl-kicker';kicker.textContent=product.category;const title=document.createElement('h1');title.className='wl-title';title.textContent=product.title;const description=document.createElement('p');description.className='wl-subtitle';description.textContent=product.description||'Produit proposé directement par un producteur local.';const meta=document.createElement('div');meta.className='wl-product-detail-meta';const price=document.createElement('strong');price.className='wl-price';price.textContent=money(product.priceXaf)+' / '+text(product.unit);const availability=document.createElement('span');availability.className='wl-status '+(product.availability.state==='LOW_STOCK'?'is-warning':'');availability.textContent=statusLabel[product.availability.state]||product.availability.state;meta.append(price,availability);const producer=document.createElement('p');producer.className='wl-muted';producer.textContent='Proposé par '+text(product.producer?.name||'Producteur local')+' · '+text(product.location);const actions=document.createElement('div');actions.className='wl-intro-actions';const request=document.createElement('button');request.className='wl-btn accent';request.type='button';request.textContent='Ajouter à la commande';request.addEventListener('click',()=>{const target='/commande?productId='+encodeURIComponent(product.id);if(!localStorage.getItem('wl_token')){location.href='/connexion?next='+encodeURIComponent(target);return}location.href=target});actions.append(request);copy.append(kicker,title,description,meta,producer,actions);root.append(media,copy)}async function load(){try{const response=await fetch('/api/products/'+encodeURIComponent(productId));const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Produit introuvable.');render(data.product)}catch(error){root.innerHTML='<div class="wl-alert error">'+text(error.message)+'</div>'}}load();
`;
  return layout('Fiche produit', content, script);
}

export function renderOrderPage() {
  const content = `<main class="wl-page"><a class="wl-back-link" href="/catalogue">← Retour au catalogue</a><section class="wl-intro"><div><p class="wl-kicker">Votre commande</p><h1 class="wl-title">Préparez votre panier.</h1><p class="wl-subtitle">Ajoutez, diminuez ou retirez vos produits. Quand tout est prêt, validez : Weli-Link vous met en relation sur WhatsApp.</p></div><div class="wl-intro-actions"><a class="wl-btn" href="/acheteur">Mes commandes</a><a class="wl-btn" href="/assistant">Parler à Weli</a></div></section><section class="wl-grid two"><article class="wl-card"><div class="wl-section-head"><div><p class="wl-kicker">Panier</p><h2 id="cart-count">0 produit</h2></div><a class="wl-btn" href="/catalogue">Ajouter des produits</a></div><div id="cart-list" class="wl-list"><div class="wl-empty">Votre panier est vide.</div></div></article><aside class="wl-card"><p class="wl-kicker">Validation</p><h2>Une commande simple et directe.</h2><p>Après validation, le producteur est informé et vous poursuivez l’échange avec Weli-Link sur WhatsApp pour organiser la suite.</p><div class="wl-field" style="margin-top:18px"><label for="order-pickup">Lieu ou indication de livraison</label><input id="order-pickup" maxlength="120" placeholder="Quartier, ville ou retrait à convenir"></div><div id="cart-total" class="wl-alert" style="margin-top:14px">Total : 0 F</div><div id="cart-message" class="wl-alert" style="margin-top:12px" hidden role="status"></div><button id="checkout-button" class="wl-btn accent" type="button" style="width:100%;margin-top:14px" disabled>Valider et continuer sur WhatsApp</button></aside></section></main><footer class="wl-footer">Weli-Link Market · Commande</footer>`;
  const script = `
const cartKey='wl_cart';const token=localStorage.getItem('wl_token');let currentUser=null;try{currentUser=JSON.parse(localStorage.getItem('wl_user')||'null')}catch(_error){localStorage.removeItem('wl_user')}const list=document.querySelector('#cart-list');const count=document.querySelector('#cart-count');const totalBox=document.querySelector('#cart-total');const checkout=document.querySelector('#checkout-button');const message=document.querySelector('#cart-message');const pickup=document.querySelector('#order-pickup');const money=(value)=>new Intl.NumberFormat('fr-FR').format(value)+' F';const esc=(value)=>String(value??'').replace(/[&<>\"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[character]));const readCart=()=>{try{const value=JSON.parse(localStorage.getItem(cartKey)||'[]');return Array.isArray(value)?value.filter(item=>item&&item.id&&Number.isInteger(item.quantity)&&item.quantity>0):[]}catch(_error){return []}};let cart=readCart();const saveCart=()=>localStorage.setItem(cartKey,JSON.stringify(cart));const productImage=(item)=>item.imageUrl?'<img src=\"'+esc(item.imageUrl)+'\" alt=\"\" loading=\"lazy\">':'<span>'+esc(item.title)+'</span>';function render(){const total=cart.reduce((sum,item)=>sum+item.priceXaf*item.quantity,0);const units=cart.reduce((sum,item)=>sum+item.quantity,0);count.textContent=units+' produit'+(units>1?'s':'');totalBox.textContent='Total : '+money(total);checkout.disabled=cart.length===0;list.innerHTML=cart.length?cart.map(item=>'<div class=\"wl-row wl-cart-row\"><div class=\"wl-cart-media\">'+productImage(item)+'</div><div class=\"wl-row-main\"><strong>'+esc(item.title)+'</strong><span>'+money(item.priceXaf)+' / '+esc(item.unit)+' · '+esc(item.location)+'</span><b class=\"wl-cart-line-total\">'+money(item.priceXaf*item.quantity)+'</b></div><div class=\"wl-cart-controls\"><button class=\"wl-btn\" type=\"button\" data-decrease=\"'+esc(item.id)+'\" aria-label=\"Diminuer la quantité de '+esc(item.title)+'\">−</button><span aria-live=\"polite\">'+item.quantity+'</span><button class=\"wl-btn\" type=\"button\" data-increase=\"'+esc(item.id)+'\" aria-label=\"Ajouter une unité de '+esc(item.title)+'\">+</button><button class=\"wl-btn danger\" type=\"button\" data-remove=\"'+esc(item.id)+'\">Supprimer</button></div></div>').join(''):'<div class=\"wl-empty\">Votre panier est vide.<br><a href=\"/catalogue\">Découvrir les produits</a></div>';document.querySelectorAll('[data-increase]').forEach(button=>button.addEventListener('click',()=>changeQuantity(button.dataset.increase,1)));document.querySelectorAll('[data-decrease]').forEach(button=>button.addEventListener('click',()=>changeQuantity(button.dataset.decrease,-1)));document.querySelectorAll('[data-remove]').forEach(button=>button.addEventListener('click',()=>{cart=cart.filter(item=>item.id!==button.dataset.remove);saveCart();render()}))}function changeQuantity(id,delta){const item=cart.find(entry=>entry.id===id);if(!item)return;item.quantity+=delta;if(item.quantity<=0)cart=cart.filter(entry=>entry.id!==id);saveCart();render()}async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(token)headers.Authorization='Bearer '+token;const response=await fetch(path,{...options,headers});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Une erreur est survenue.');return data}function addItem(product,quantity=1){const item=cart.find(entry=>entry.id===product.id);if(item)item.quantity+=quantity;else cart.push({id:product.id,title:product.title,priceXaf:product.priceXaf,unit:product.unit,location:product.location,imageUrl:product.imageUrl,quantity});saveCart();render()}async function addProductFromQuery(){const productId=new URLSearchParams(location.search).get('productId');if(!productId)return;try{const data=await api('/api/products/'+encodeURIComponent(productId));addItem(data.product);history.replaceState({},'', '/commande')}catch(error){message.hidden=false;message.className='wl-alert error';message.textContent=error.message}}checkout.addEventListener('click',async()=>{if(!token){location.href='/connexion?next='+encodeURIComponent('/commande');return}checkout.disabled=true;checkout.textContent='Validation…';message.hidden=true;try{const data=await api('/api/orders/checkout',{method:'POST',body:JSON.stringify({items:cart.map(item=>({productId:item.id,quantity:item.quantity})),requestedPickup:pickup.value.trim()||undefined})});const lines=cart.map(item=>'- '+item.title+' : '+item.quantity+' '+item.unit+' = '+money(item.priceXaf*item.quantity));const total=cart.reduce((sum,item)=>sum+item.priceXaf*item.quantity,0);const producers=[...new Set(data.requests.map(item=>item.producer?.name).filter(Boolean))];const text=['Bonjour Weli-Link Market,','Je souhaite organiser cette commande :','',...lines,'','Total indicatif : '+money(total),'Acheteur : '+(currentUser?.name||'Utilisateur Weli-Link'),'Lieu / indication : '+(pickup.value.trim()||'À convenir'),producers.length?'Producteur(s) : '+producers.join(', '):'', 'Référence(s) Weli-Link : '+data.requests.map(item=>item.id).join(', ')].filter(Boolean).join('\\n');localStorage.removeItem(cartKey);cart=[];window.location.href='https://wa.me/237670785644?text='+encodeURIComponent(text)}catch(error){message.hidden=false;message.className='wl-alert error';message.textContent=error.message;checkout.disabled=false;checkout.textContent='Valider et continuer sur WhatsApp'}});render();addProductFromQuery();
`;
  return layout('Commande', content, script);
}

export function renderBuyerPage() {
  const content = `<main class="wl-page"><section class="wl-intro"><div><p class="wl-kicker">Votre espace acheteur</p><h1 class="wl-title">Acheter local, simplement.</h1><p class="wl-subtitle">Choisissez un produit, envoyez votre commande au producteur et organisez la livraison directement avec lui.</p></div><div class="wl-intro-actions"><a class="wl-btn accent" href="/catalogue">Voir le catalogue</a><a class="wl-btn" href="/assistant">Parler à Weli</a><button class="wl-btn danger" data-logout>Se déconnecter</button></div></section><section class="wl-grid four"><article class="wl-card"><p class="wl-kicker">Étape 01</p><h2>Choisir</h2><p>Consultez les offres locales et les disponibilités réelles.</p></article><article class="wl-card"><p class="wl-kicker">Étape 02</p><h2>Commander</h2><p>Indiquez la quantité et le lieu souhaité au producteur.</p></article><article class="wl-card"><p class="wl-kicker">Étape 03</p><h2>Organiser</h2><p>Le producteur reçoit une notification et confirme la commande.</p></article><article class="wl-card"><p class="wl-kicker">Étape 04</p><h2>Confirmer</h2><p>Après livraison ou retrait, confirmez la bonne réception.</p></article></section><section class="wl-section"><div class="wl-section-head"><div><p class="wl-kicker">À découvrir</p><h2>Offres disponibles</h2></div><a class="wl-btn" href="/catalogue">Tout le catalogue</a></div><div id="buyer-products" class="wl-grid"><div class="wl-empty">Chargement…</div></div></section><section class="wl-section"><div class="wl-section-head"><div><p class="wl-kicker">Suivi de vos achats</p><h2>Mes commandes</h2></div></div><div class="wl-alert" style="margin-bottom:15px">Weli ne prend pas de paiement en ligne. Le règlement et la livraison se font directement entre l’acheteur et le producteur.</div><div id="buyer-requests" class="wl-card"><div class="wl-empty">Chargement…</div></div></section></main><footer class="wl-footer">Weli-Link Market · Espace acheteur</footer>`;
  const script = `${protectedGuard}
if(!user||user.role!=='BUYER'){location.href=user&&user.role==='PRODUCER'?'/producteur':'/admin'}const productsBox=document.querySelector('#buyer-products');const requestsBox=document.querySelector('#buyer-requests');const token=localStorage.getItem('wl_token');const cartKey='wl_cart';let catalogProducts=[];const esc=(v)=>String(v??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const money=(v)=>new Intl.NumberFormat('fr-FR').format(v)+' F';const labels={PENDING:'En attente du producteur',ACCEPTED:'Commande confirmée',CANCELLATION_REQUESTED:'Annulation à examiner',COMPLETED:'Réception confirmée',REJECTED:'Indisponible',CANCELLED:'Commande annulée',EXPIRED:'Expirée'};async function api(path,options={}){const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',Authorization:'Bearer '+token,...(options.headers||{})}});const data=await res.json();if(!res.ok)throw new Error(data.error?.message||'Une erreur est survenue.');return data}function productCard(p){return '<article class="wl-card wl-product"><div class="wl-product-photo">'+esc(p.title)+'</div><div><h3><a class="wl-product-title" href="/produit/'+encodeURIComponent(p.id)+'">'+esc(p.title)+'</a></h3><p>'+esc(p.location)+' · '+esc(p.unit)+'</p><span class="wl-status">'+(p.availability.state==='LOW_STOCK'?'Stock faible':'Disponible')+'</span></div><div class="wl-product-meta"><span class="wl-price">'+money(p.priceXaf)+'</span><button class="wl-btn accent" data-request="'+p.id+'">Commander</button></div></article>'}function orderActions(r){if(r.status==='PENDING')return '<button class="wl-btn danger" data-cancel-order="'+r.id+'">Annuler</button>';if(r.status==='ACCEPTED')return '<button class="wl-btn accent" data-confirm-receipt="'+r.id+'">Confirmer la réception</button><button class="wl-btn" data-request-cancellation="'+r.id+'">Signaler un problème</button>';if(r.status==='CANCELLATION_REQUESTED')return '<span class="wl-live-note">Votre justificatif a été transmis au producteur.</span>';return ''}function renderOrders(requests){return requests.length?'<div class="wl-list">'+requests.map(r=>'<div class="wl-row"><div class="wl-row-main"><strong>'+esc(r.product.title)+'</strong><span>'+r.quantity+' '+esc(r.product.unit)+' · '+money(r.totalXaf)+' · '+esc(r.producer.name)+'</span></div><div class="wl-row-actions"><span class="wl-pill '+(r.status==='REJECTED'||r.status==='CANCELLED'?'red':r.status==='COMPLETED'?'':'yellow')+'">'+esc(labels[r.status]||r.status)+'</span>'+orderActions(r)+'</div></div>').join('')+'</div>':'<div class="wl-empty">Vous n’avez pas encore passé de commande.</div>'}async function load(){try{const data=await Promise.all([api('/api/products'),api('/api/requests/mine')]);catalogProducts=data[0].products;const visibleProducts=catalogProducts.slice(0,6);wlRegisterProductImages(catalogProducts);productsBox.innerHTML=visibleProducts.map(productCard).join('')||'<div class="wl-empty">Aucune offre pour le moment.</div>';wlRegisterProductImages(visibleProducts);requestsBox.innerHTML=renderOrders(data[1].requests);bindActions()}catch(error){productsBox.innerHTML='<div class="wl-alert error">'+esc(error.message)+'</div>';requestsBox.innerHTML='<div class="wl-alert error">'+esc(error.message)+'</div>'}}function bindActions(){document.querySelectorAll('[data-request]').forEach((button)=>button.addEventListener('click',()=>{const product=catalogProducts.find((item)=>item.id===button.dataset.request);if(!product)return;let cart=[];try{const stored=JSON.parse(localStorage.getItem(cartKey)||'[]');if(Array.isArray(stored))cart=stored}catch(_error){}const item=cart.find((entry)=>entry.id===product.id);if(item)item.quantity=(Number(item.quantity)||0)+1;else cart.push({id:product.id,title:product.title,priceXaf:product.priceXaf,unit:product.unit,location:product.location,imageUrl:product.imageUrl,quantity:1});localStorage.setItem(cartKey,JSON.stringify(cart));location.href='/commande'}));document.querySelectorAll('[data-cancel-order]').forEach((button)=>button.addEventListener('click',async()=>{if(!confirm('Annuler cette commande avant la confirmation du producteur ?'))return;try{await api('/api/requests/'+button.dataset.cancelOrder+'/cancel',{method:'POST'});await load()}catch(error){alert(error.message)}}));document.querySelectorAll('[data-confirm-receipt]').forEach((button)=>button.addEventListener('click',async()=>{if(!confirm('Confirmer que vous avez bien reçu cette commande ?'))return;try{await api('/api/requests/'+button.dataset.confirmReceipt+'/confirm-receipt',{method:'POST'});await load()}catch(error){alert(error.message)}}));document.querySelectorAll('[data-request-cancellation]').forEach((button)=>button.addEventListener('click',async()=>{const evidence=window.prompt('Expliquez le problème et fournissez le justificatif disponible (minimum 10 caractères) :','Commande non reçue malgré la confirmation');if(!evidence||evidence.trim().length<10)return;try{await api('/api/requests/'+button.dataset.requestCancellation+'/cancellation',{method:'POST',body:JSON.stringify({evidence})});alert('Votre demande d’annulation a été transmise au producteur.');await load()}catch(error){alert(error.message)}}))}load();window.setInterval(load,20000);
`;
  return layout('Espace acheteur', content, script);
}

export function renderProducerPage() {
  const content = `<main class="wl-dashboard"><div class="wl-dashboard-layout"><aside class="wl-dashboard-aside"><div class="wl-dashboard-person"><span id="producer-avatar" class="wl-avatar">WL</span><div><strong id="producer-name">Votre ferme</strong><span>Compte producteur</span></div></div><nav class="wl-dashboard-nav" aria-label="Navigation producteur"><button class="active" type="button" data-producer-panel="overview">Vue d’ensemble</button><button type="button" data-producer-panel="offers">Mes offres</button><button type="button" data-producer-panel="requests">Demandes reçues</button><button type="button" data-producer-panel="stock">Stock & disponibilité</button><button type="button" data-producer-panel="weli">Parler à Weli</button></nav><div class="wl-dashboard-aside-foot"><a class="wl-btn" href="/catalogue">Voir le marché</a><button class="wl-btn danger" data-logout type="button">Se déconnecter</button></div></aside><section class="wl-dashboard-main"><header class="wl-dashboard-hero"><div><p class="wl-kicker">Espace producteur</p><h1 class="wl-title">Votre marché, sous contrôle.</h1><p class="wl-subtitle">Publiez vos offres, gardez votre stock juste et répondez aux acheteurs au bon moment.</p></div><div class="wl-dashboard-actions"><a class="wl-btn" href="/notifications">Notifications</a><button class="wl-btn accent" type="button" data-producer-panel="offers">+ Publier une offre</button></div></header><section id="producer-panel-overview" class="wl-dashboard-panel"><div id="producer-metrics" class="wl-grid four"><article class="wl-card wl-metric"><p class="wl-kicker">Chargement</p><h2>—</h2></article></div><div class="wl-dashboard-section wl-grid two"><article class="wl-card"><div class="wl-dashboard-card-title"><div><p class="wl-kicker">À traiter</p><h2>Demandes récentes</h2></div><button class="wl-btn" type="button" data-producer-panel="requests">Tout voir</button></div><div id="producer-overview-requests"><div class="wl-empty">Chargement…</div></div></article><article class="wl-card"><div class="wl-dashboard-card-title"><div><p class="wl-kicker">Vigilance</p><h2>Stock à vérifier</h2></div><button class="wl-btn" type="button" data-producer-panel="stock">Gérer le stock</button></div><div id="producer-attention"><div class="wl-empty">Chargement…</div></div></article></div><section class="wl-dashboard-section"><div class="wl-section-head"><div><p class="wl-kicker">Vos dernières offres</p><h2>Ce que voient les acheteurs</h2></div><button class="wl-btn" type="button" data-producer-panel="offers">Gérer mes offres</button></div><div id="producer-overview-products" class="wl-card"><div class="wl-empty">Chargement…</div></div></section></section><section id="producer-panel-offers" class="wl-dashboard-panel" hidden><div class="wl-grid two"><article class="wl-card"><p class="wl-kicker">Nouvelle offre</p><h2>Publier un produit</h2><p>Ajoutez un vivre frais ou un produit transformé. Le prix reste fixé par vous.</p><form id="product-form" class="wl-form" style="margin-top:15px" enctype="multipart/form-data"><div class="wl-form-grid"><div class="wl-field"><label>Produit</label><input name="title" required placeholder="Miel de forêt"></div><div class="wl-field"><label>Type</label><select name="kind"><option value="FRESH">Vivre frais</option><option value="PROCESSED">Produit transformé</option></select></div><div class="wl-field"><label>Catégorie</label><input name="category" required placeholder="Produits transformés"></div><div class="wl-field"><label>Unité</label><input name="unit" required placeholder="pot de 500 g"></div><div class="wl-field"><label>Prix en FCFA</label><input name="priceXaf" type="number" required min="1" placeholder="4500"></div><div class="wl-field"><label>Quantité</label><input name="quantity" type="number" required min="0" placeholder="20"></div><div class="wl-field full"><label>Localisation</label><input name="location" required placeholder="Yaoundé · Centre"></div><div class="wl-field full"><label>Description</label><textarea name="description" placeholder="Origine du produit, conditions de retrait, qualité…"></textarea></div><div class="wl-field full"><label for="product-image">Photo du produit <span class="wl-muted">(facultative)</span></label><div class="wl-image-picker"><input id="product-image" name="image" type="file" accept="image/jpeg,image/png,image/webp" aria-describedby="product-image-help"><div id="product-image-preview" class="wl-image-preview"><span>Aperçu</span><button id="product-image-remove" type="button" hidden aria-label="Retirer la photo">×</button></div></div><p id="product-image-help" class="wl-image-help">JPG, PNG ou WebP · 5 Mo maximum. Une photo principale suffit pour commencer.</p></div></div><div id="product-message" class="wl-alert" hidden></div><div class="wl-form-actions"><button class="wl-btn primary" type="submit">Publier l’offre</button></div></form></article><article class="wl-card wl-admin-note"><p class="wl-kicker">La promesse Weli</p><h2>Vous décidez toujours.</h2><p>Une demande devient une commande après votre acceptation. Organisez ensuite la livraison ou le retrait directement avec l’acheteur ; aucun paiement ne passe par Weli.</p><div class="wl-live-note">Actualisez les produits frais dès que le stock change.</div></article></div><section class="wl-dashboard-section"><div class="wl-section-head"><div><p class="wl-kicker">Catalogue personnel</p><h2>Mes offres publiées</h2></div></div><div id="producer-products-list" class="wl-card"><div class="wl-empty">Chargement…</div></div></section></section><section id="producer-panel-requests" class="wl-dashboard-panel" hidden><div class="wl-section-head"><div><p class="wl-kicker">Demandes d’achat</p><h2>Répondez sans attendre.</h2><p class="wl-subtitle">Acceptez ou refusez : l’acheteur est automatiquement notifié et le stock est mis à jour.</p></div></div><div id="producer-requests-list" class="wl-card"><div class="wl-empty">Chargement…</div></div></section><section id="producer-panel-stock" class="wl-dashboard-panel" hidden><div class="wl-section-head"><div><p class="wl-kicker">Disponibilité</p><h2>Mettre à jour le stock.</h2><p class="wl-subtitle">Cette donnée est celle que Weli utilise pour répondre aux acheteurs.</p></div></div><div id="producer-stock-list" class="wl-card"><div class="wl-empty">Chargement…</div></div></section><section id="producer-panel-weli" class="wl-dashboard-panel" hidden><div class="wl-grid two"><article class="wl-card wl-ai"><p class="wl-kicker">Weli IA</p><h2>Préparez une réponse acheteur.</h2><p>Weli consulte la disponibilité enregistrée dans votre catalogue avant de répondre.</p><div id="producer-weli-result" class="wl-chat"><div class="wl-bubble">Exemple : « Le miel est-il encore disponible à Yaoundé ? »</div></div><form id="producer-weli-form" class="wl-chat-inline"><input name="message" required placeholder="Posez une question à Weli"><button class="wl-btn accent" type="submit">Envoyer</button></form></article><article class="wl-card"><p class="wl-kicker">Astuce</p><h2>Une réponse fiable commence par le stock.</h2><p>Si une offre fraîche n’a pas été mise à jour à temps, Weli indiquera qu’une reconfirmation est nécessaire au lieu de promettre une quantité incertaine.</p></article></div></section></section></div></main><footer class="wl-footer">Weli-Link Market · Espace producteur</footer>`;
  const script = `${protectedGuard}
const producerToken=localStorage.getItem('wl_token');const producerEsc=(value)=>String(value??'').replace(/[&<>\"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[character]));const producerMoney=(value)=>new Intl.NumberFormat('fr-FR').format(value)+' F';const producerLabels={AVAILABLE:'Disponible',LOW_STOCK:'Stock faible',CHECK_REQUIRED:'À reconfirmer',OUT_OF_STOCK:'Rupture',PAUSED:'Suspendue',PENDING:'En attente',ACCEPTED:'Acceptée',REJECTED:'Refusée',CANCELLATION_REQUESTED:'Annulation à examiner',CANCELLED:'Annulée',COMPLETED:'Réception confirmée',EXPIRED:'Expirée',SUCCEEDED:'Confirmé',INITIATED:'En attente'};let producerDashboard=null;const producerApi=async(path,options={})=>{const headers={Authorization:'Bearer '+producerToken,...(options.headers||{})};if(!(options.body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch(path,{...options,headers});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Une erreur est survenue.');return data};const producerLabel=(value)=>producerLabels[value]||value;const producerChatKey=()=>{let key=localStorage.getItem('wl_chat_key');if(!key){key=crypto.randomUUID();localStorage.setItem('wl_chat_key',key)}return key};function selectProducerPanel(name){document.querySelectorAll('[data-producer-panel]').forEach(button=>button.classList.toggle('active',button.dataset.producerPanel===name));document.querySelectorAll('[id^="producer-panel-"]').forEach(panel=>{panel.hidden=panel.id!=='producer-panel-'+name})}function requestRows(requests,limit){const rows=requests.slice(0,limit);return rows.length?'<div class="wl-list">'+rows.map(requestItem=>'<div class="wl-row '+(requestItem.status==='PENDING'||requestItem.status==='CANCELLATION_REQUESTED'?'wl-request-highlight':'')+'"><div class="wl-row-main"><strong>'+producerEsc(requestItem.product.title)+'</strong><span>'+producerEsc(requestItem.buyer.name)+' commande '+requestItem.quantity+' '+producerEsc(requestItem.product.unit)+' · '+producerMoney(requestItem.totalXaf)+'</span>'+(requestItem.status==='CANCELLATION_REQUESTED'?'<small class="wl-live-note">Justificatif : '+producerEsc(requestItem.cancellationEvidence||'Non précisé')+'</small>':'')+'</div><div class="wl-row-actions"><span class="wl-pill '+(requestItem.status==='PENDING'||requestItem.status==='CANCELLATION_REQUESTED'?'yellow':'')+'">'+producerEsc(producerLabel(requestItem.status))+'</span>'+(requestItem.status==='PENDING'?'<button class="wl-btn primary" type="button" data-producer-decision="ACCEPTED" data-request-id="'+requestItem.id+'">Confirmer</button><button class="wl-btn danger" type="button" data-producer-decision="REJECTED" data-request-id="'+requestItem.id+'">Refuser</button>':'')+(requestItem.status==='CANCELLATION_REQUESTED'?'<button class="wl-btn primary" type="button" data-cancellation-decision="APPROVED" data-request-id="'+requestItem.id+'">Accepter l’annulation</button><button class="wl-btn" type="button" data-cancellation-decision="REJECTED" data-request-id="'+requestItem.id+'">Maintenir</button>':'')+'</div></div>').join('')+'</div>':'<div class="wl-empty">Aucune commande à afficher pour le moment.</div>'}function productRows(products,forStock){return products.length?'<div class="wl-list">'+products.map(product=>'<div class="wl-compact-product"><div><strong>'+producerEsc(product.title)+'</strong><span>'+product.quantity+' '+producerEsc(product.unit)+' · '+producerMoney(product.priceXaf)+' · '+producerEsc(product.location)+'</span></div>'+(forStock?'<div class="wl-stock-control"><span class="wl-pill '+(product.availability.state==='AVAILABLE'?'':'yellow')+'">'+producerEsc(producerLabel(product.availability.state))+'</span><input type="number" min="0" value="'+product.quantity+'" data-stock-input="'+product.id+'" aria-label="Quantité '+producerEsc(product.title)+'"><button class="wl-btn primary" type="button" data-save-stock="'+product.id+'">Mettre à jour</button></div>':'<span class="wl-pill '+(product.availability.state==='AVAILABLE'?'':'yellow')+'">'+producerEsc(producerLabel(product.availability.state))+'</span>')+'</div>').join('')+'</div>':'<div class="wl-empty">Vous n’avez pas encore publié d’offre.</div>'}function bindProducerActions(){document.querySelectorAll('[data-producer-decision]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{await producerApi('/api/requests/'+button.dataset.requestId+'/status',{method:'PATCH',body:JSON.stringify({status:button.dataset.producerDecision})});await loadProducerDashboard()}catch(error){alert(error.message)}finally{button.disabled=false}}));document.querySelectorAll('[data-cancellation-decision]').forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{await producerApi('/api/requests/'+button.dataset.requestId+'/cancellation',{method:'PATCH',body:JSON.stringify({decision:button.dataset.cancellationDecision})});await loadProducerDashboard()}catch(error){alert(error.message)}finally{button.disabled=false}}));document.querySelectorAll('[data-save-stock]').forEach(button=>button.addEventListener('click',async()=>{const input=document.querySelector('[data-stock-input="'+button.dataset.saveStock+'"]');button.disabled=true;try{await producerApi('/api/products/'+button.dataset.saveStock+'/stock',{method:'PATCH',body:JSON.stringify({quantity:Number(input.value)})});await loadProducerDashboard()}catch(error){alert(error.message)}finally{button.disabled=false}}))}function renderProducerDashboard(){const data=producerDashboard;const metrics=data.metrics;document.querySelector('#producer-metrics').innerHTML='<article class="wl-card wl-metric"><p class="wl-kicker">Offres publiées</p><h2>'+metrics.publishedProducts+'</h2><p>produits dans votre catalogue</p></article><article class="wl-card wl-metric"><p class="wl-kicker">À traiter</p><h2>'+metrics.pendingRequests+'</h2><p>demandes attendent votre réponse</p></article><article class="wl-card wl-metric"><p class="wl-kicker">Vigilance stock</p><h2>'+metrics.attentionProducts+'</h2><p>offres à vérifier ou actualiser</p></article><article class="wl-card wl-metric"><p class="wl-kicker">Commandes finalisées</p><h2>'+producerMoney(metrics.completedOrdersXaf)+'</h2><p>réceptions confirmées</p></article>';document.querySelector('#producer-overview-requests').innerHTML=requestRows(data.requests,4);document.querySelector('#producer-requests-list').innerHTML=requestRows(data.requests,50);document.querySelector('#producer-overview-products').innerHTML=productRows(data.products.slice(0,5),false);document.querySelector('#producer-products-list').innerHTML=productRows(data.products,false);document.querySelector('#producer-stock-list').innerHTML=productRows(data.products,true);document.querySelector('#producer-attention').innerHTML=data.attentionProducts.length?productRows(data.attentionProducts,false):'<div class="wl-empty">Très bien : aucune offre ne demande votre attention.</div>';bindProducerActions()}async function loadProducerDashboard(){try{producerDashboard=await producerApi('/api/dashboard/producer');renderProducerDashboard()}catch(error){document.querySelector('#producer-metrics').innerHTML='<div class="wl-alert error">'+producerEsc(error.message)+'</div>'}}async function startProducer(){try{const me=await producerApi('/api/me');if(me.user.role!=='PRODUCER'){location.href=me.user.role==='ADMIN'?'/admin':'/acheteur';return}document.querySelector('#producer-name').textContent=me.user.name;document.querySelector('#producer-avatar').textContent=me.user.name.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();await loadProducerDashboard()}catch(_error){logout()}}document.querySelectorAll('[data-producer-panel]').forEach(button=>button.addEventListener('click',()=>selectProducerPanel(button.dataset.producerPanel)));const productForm=document.querySelector('#product-form');const productImageInput=document.querySelector('#product-image');const productImagePreview=document.querySelector('#product-image-preview');const productImageRemove=document.querySelector('#product-image-remove');let productImageObjectUrl=null;const clearProductImagePreview=()=>{if(productImageObjectUrl)URL.revokeObjectURL(productImageObjectUrl);productImageObjectUrl=null;productImagePreview.replaceChildren(document.createTextNode('Aperçu'));productImageRemove.hidden=true;productImageInput.value=''};productImageInput.addEventListener('change',()=>{const file=productImageInput.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){productImageInput.value='';productImagePreview.replaceChildren(document.createTextNode('Format ou taille invalide'));productImageRemove.hidden=false;return}if(productImageObjectUrl)URL.revokeObjectURL(productImageObjectUrl);productImageObjectUrl=URL.createObjectURL(file);const image=document.createElement('img');image.src=productImageObjectUrl;image.alt='Aperçu de la photo du produit';productImagePreview.replaceChildren(image,productImageRemove);productImageRemove.hidden=false});productImageRemove.addEventListener('click',clearProductImagePreview);productForm.addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget;const message=document.querySelector('#product-message');const submit=form.querySelector('button[type="submit"]');message.hidden=false;message.className='wl-alert';message.textContent='Publication en cours…';submit.disabled=true;submit.setAttribute('aria-busy','true');try{await producerApi('/api/products',{method:'POST',body:new FormData(form)});message.textContent='Votre offre est publiée et visible dans le catalogue.';form.reset();clearProductImagePreview();await loadProducerDashboard()}catch(error){message.className='wl-alert error';message.textContent=error.message}finally{submit.disabled=false;submit.removeAttribute('aria-busy')}});document.querySelector('#producer-weli-form').addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget;const input=form.querySelector('input');const result=document.querySelector('#producer-weli-result');const message=input.value.trim();if(!message)return;result.innerHTML='<div class="wl-bubble user">'+producerEsc(message)+'</div><div class="wl-bubble">Weli vérifie le catalogue…</div>';try{const data=await producerApi('/api/assistant/chat',{method:'POST',body:JSON.stringify({message,conversationKey:producerChatKey()})});localStorage.setItem('wl_chat_key',data.conversationKey);result.innerHTML='<div class="wl-bubble user">'+producerEsc(message)+'</div><div class="wl-bubble">'+producerEsc(data.reply)+'</div>';input.value=''}catch(error){result.innerHTML='<div class="wl-alert error">'+producerEsc(error.message)+'</div>'}});startProducer();window.setInterval(loadProducerDashboard,30000);
`;
  return layout('Espace producteur', content, script);
}

export function renderAdminPage() {
  const content = `<main class="wl-dashboard"><div class="wl-dashboard-layout"><aside class="wl-dashboard-aside"><div class="wl-dashboard-person"><span id="admin-avatar" class="wl-avatar">WL</span><div><strong id="admin-name">Administration</strong><span>Supervision du marché</span></div></div><nav class="wl-dashboard-nav" aria-label="Navigation administration"><button class="active" type="button" data-admin-panel="overview">Vue d’ensemble</button><button type="button" data-admin-panel="market">Offres & disponibilité</button><button type="button" data-admin-panel="requests">Demandes</button><button type="button" data-admin-panel="users">Utilisateurs</button></nav><div class="wl-dashboard-aside-foot"><a class="wl-btn" href="/catalogue">Voir le catalogue</a><button class="wl-btn danger" data-logout type="button">Se déconnecter</button></div></aside><section class="wl-dashboard-main"><header class="wl-dashboard-hero"><div><p class="wl-kicker">Administration Weli-Link</p><h1 class="wl-title">Garder le marché sain.</h1><p class="wl-subtitle">Suivez les échanges, les offres et les demandes sans perturber les décisions des producteurs.</p></div><div class="wl-dashboard-actions"><a class="wl-btn" href="/notifications">Notifications</a><a class="wl-btn accent" href="/catalogue">Voir le marché</a></div></header><section id="admin-panel-overview" class="wl-dashboard-panel"><div id="admin-metrics" class="wl-grid four"><article class="wl-card wl-metric"><p class="wl-kicker">Chargement</p><h2>—</h2></article></div><div class="wl-dashboard-section wl-grid two"><article class="wl-card"><div class="wl-dashboard-card-title"><div><p class="wl-kicker">À surveiller</p><h2>Dernières demandes</h2></div><button class="wl-btn" type="button" data-admin-panel="requests">Tout voir</button></div><div id="admin-overview-requests"><div class="wl-empty">Chargement…</div></div></article><article class="wl-card"><div class="wl-dashboard-card-title"><div><p class="wl-kicker">Qualité du catalogue</p><h2>Offres à vérifier</h2></div><button class="wl-btn" type="button" data-admin-panel="market">Gérer</button></div><div id="admin-attention"><div class="wl-empty">Chargement…</div></div></article></div><section class="wl-dashboard-section"><article class="wl-card wl-admin-note"><p class="wl-kicker">Règle de gouvernance</p><h2>Le producteur garde la main sur le prix et l’acceptation.</h2><p>L’administration supervise les données, suspend si nécessaire une offre et suit les transactions ; elle ne confirme pas un stock à la place du producteur.</p></article></section></section><section id="admin-panel-market" class="wl-dashboard-panel" hidden><div class="wl-section-head"><div><p class="wl-kicker">Catalogue partagé</p><h2>Offres & disponibilité.</h2><p class="wl-subtitle">Une offre peut être suspendue en cas de problème. Le stock reste mis à jour par son producteur.</p></div></div><div id="admin-products-list" class="wl-card"><div class="wl-empty">Chargement…</div></div></section><section id="admin-panel-requests" class="wl-dashboard-panel" hidden><div class="wl-section-head"><div><p class="wl-kicker">Traçabilité</p><h2>Demandes d’achat.</h2><p class="wl-subtitle">Suivez leur statut ; le producteur est le seul à pouvoir accepter ou refuser.</p></div></div><div id="admin-requests-list" class="wl-card"><div class="wl-empty">Chargement…</div></div></section><section id="admin-panel-users" class="wl-dashboard-panel" hidden><div class="wl-section-head"><div><p class="wl-kicker">Comptes</p><h2>Utilisateurs récents.</h2><p class="wl-subtitle">Les administrateurs sont créés par l’équipe Weli, pas depuis l’inscription publique.</p></div></div><div id="admin-users-list" class="wl-card"><div class="wl-empty">Chargement…</div></div></section></section></div></main><footer class="wl-footer">Weli-Link Market · Administration</footer>`;
  const script = `${protectedGuard}
const adminToken=localStorage.getItem('wl_token');const adminEsc=(value)=>String(value??'').replace(/[&<>\"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[character]));const adminMoney=(value)=>new Intl.NumberFormat('fr-FR').format(value)+' F';const adminLabels={AVAILABLE:'Disponible',LOW_STOCK:'Stock faible',CHECK_REQUIRED:'À reconfirmer',OUT_OF_STOCK:'Rupture',PAUSED:'Suspendue',PENDING:'En attente',ACCEPTED:'Acceptée',REJECTED:'Refusée',CANCELLED:'Annulée',EXPIRED:'Expirée',BUYER:'Acheteur',PRODUCER:'Producteur',ADMIN:'Administrateur'};let adminDashboard=null;const adminApi=async(path,options={})=>{const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',Authorization:'Bearer '+adminToken,...(options.headers||{})}});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Une erreur est survenue.');return data};const adminLabel=(value)=>adminLabels[value]||value;function selectAdminPanel(name){document.querySelectorAll('[data-admin-panel]').forEach(button=>button.classList.toggle('active',button.dataset.adminPanel===name));document.querySelectorAll('[id^="admin-panel-"]').forEach(panel=>{panel.hidden=panel.id!=='admin-panel-'+name})}function adminProductRows(products,interactive){return products.length?'<div class="wl-list">'+products.map(product=>'<div class="wl-compact-product"><div><strong>'+adminEsc(product.title)+'</strong><span>'+adminEsc(product.producer.name)+' · '+adminEsc(product.location)+' · '+product.quantity+' '+adminEsc(product.unit)+'</span></div><div class="wl-row-actions"><span class="wl-pill '+(product.availability.state==='AVAILABLE'?'':'yellow')+'">'+adminEsc(adminLabel(product.availability.state))+'</span>'+(interactive?'<button class="wl-btn '+(product.status==='ACTIVE'?'danger':'primary')+'" type="button" data-admin-status="'+product.id+'" data-admin-quantity="'+product.quantity+'" data-admin-next="'+(product.status==='ACTIVE'?'PAUSED':'ACTIVE')+'">'+(product.status==='ACTIVE'?'Suspendre':'Réactiver')+'</button>':'')+'</div></div>').join('')+'</div>':'<div class="wl-empty">Aucune offre à afficher.</div>'}function adminRequestRows(requests,limit){const rows=requests.slice(0,limit);return rows.length?'<div class="wl-list">'+rows.map(requestItem=>'<div class="wl-row"><div class="wl-row-main"><strong>'+adminEsc(requestItem.product.title)+'</strong><span>'+adminEsc(requestItem.buyer.name)+' → '+adminEsc(requestItem.producer.name)+' · '+requestItem.quantity+' '+adminEsc(requestItem.product.unit)+' · '+adminMoney(requestItem.totalXaf)+'</span></div><div class="wl-row-actions"><span class="wl-pill '+(requestItem.status==='PENDING'?'yellow':'')+'">'+adminEsc(adminLabel(requestItem.status))+'</span></div></div>').join('')+'</div>':'<div class="wl-empty">Aucune demande à afficher.</div>'}function bindAdminActions(){document.querySelectorAll('[data-admin-status]').forEach(button=>button.addEventListener('click',async()=>{const next=button.dataset.adminNext;const wording=next==='PAUSED'?'suspendre':'réactiver';if(!confirm('Voulez-vous '+wording+' cette offre ?'))return;button.disabled=true;try{await adminApi('/api/products/'+button.dataset.adminStatus+'/stock',{method:'PATCH',body:JSON.stringify({quantity:Number(button.dataset.adminQuantity),status:next})});await loadAdminDashboard()}catch(error){alert(error.message)}finally{button.disabled=false}}))}function renderAdminDashboard(){const data=adminDashboard;const metrics=data.metrics;document.querySelector('#admin-metrics').innerHTML='<article class="wl-card wl-metric"><p class="wl-kicker">Communauté</p><h2>'+metrics.users+'</h2><p>'+metrics.producers+' producteurs · '+metrics.buyers+' acheteurs</p></article><article class="wl-card wl-metric"><p class="wl-kicker">Offres actives</p><h2>'+metrics.activeProducts+'</h2><p>annonces visibles dans le catalogue</p></article><article class="wl-card wl-metric"><p class="wl-kicker">Demandes à suivre</p><h2>'+metrics.pendingRequests+'</h2><p>en attente de réponse producteur</p></article>';document.querySelector('#admin-overview-requests').innerHTML=adminRequestRows(data.requests,5);document.querySelector('#admin-requests-list').innerHTML=adminRequestRows(data.requests,50);document.querySelector('#admin-attention').innerHTML=data.attentionProducts.length?adminProductRows(data.attentionProducts,false):'<div class="wl-empty">Le catalogue ne présente pas d’alerte de disponibilité.</div>';document.querySelector('#admin-products-list').innerHTML=adminProductRows(data.products,true);document.querySelector('#admin-users-list').innerHTML=data.users.length?'<div class="wl-list">'+data.users.map(member=>'<div class="wl-row"><div class="wl-row-main"><strong>'+adminEsc(member.name)+'</strong><span>'+adminEsc(member.phone)+' · Compte créé le '+new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(member.createdAt))+'</span></div><span class="wl-pill">'+adminEsc(adminLabel(member.role))+'</span></div>').join('')+'</div>':'<div class="wl-empty">Aucun utilisateur récent.</div>';bindAdminActions()}async function loadAdminDashboard(){try{adminDashboard=await adminApi('/api/dashboard/admin');renderAdminDashboard()}catch(error){document.querySelector('#admin-metrics').innerHTML='<div class="wl-alert error">'+adminEsc(error.message)+'</div>'}}async function startAdmin(){try{const me=await adminApi('/api/me');if(me.user.role!=='ADMIN'){location.href=me.user.role==='PRODUCER'?'/producteur':'/acheteur';return}document.querySelector('#admin-name').textContent=me.user.name;document.querySelector('#admin-avatar').textContent=me.user.name.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();await loadAdminDashboard()}catch(_error){logout()}}document.querySelectorAll('[data-admin-panel]').forEach(button=>button.addEventListener('click',()=>selectAdminPanel(button.dataset.adminPanel)));startAdmin();window.setInterval(loadAdminDashboard,30000);
`;
  return layout('Administration', content, script);
}

function renderAssistantPageLegacy() {
  const content = `<main class="wl-page"><section class="wl-intro"><div><p class="wl-kicker">Assistant Weli</p><h1 class="wl-title">Décrivez votre besoin.</h1><p class="wl-subtitle">Weli garde le fil de cette conversation et consulte le catalogue réel avant de répondre.</p></div><div class="wl-intro-actions"><a class="wl-btn" href="/catalogue">Voir le catalogue</a><a class="wl-btn" href="/">Accueil</a></div></section><section class="wl-grid two"><article class="wl-card wl-ai"><h2>Weli est là</h2><p>Je peux chercher un produit, une quantité ou une région.</p><div id="assistant-result" class="wl-chat"><div class="wl-bubble">Bonjour ! Que cherchez-vous aujourd’hui ?</div></div><form id="assistant-form" class="wl-form"><div class="wl-field"><label>Votre question</label><input name="message" required placeholder="Le miel est-il disponible à Yaoundé ?"></div><button class="wl-btn accent" type="submit">Envoyer à Weli</button></form><div class="wl-live-note">La disponibilité affichée vient du catalogue Weli-Link.</div></article><article class="wl-card"><p class="wl-kicker">Une réponse fiable</p><h2>Pas de promesse inventée.</h2><p>Weli utilise le stock enregistré. Si la mise à jour est trop ancienne, il demande une reconfirmation au producteur au lieu d’annoncer une disponibilité incertaine.</p><div class="wl-alert" style="margin-top:15px">Le paiement est proposé uniquement après acceptation du producteur.</div></article></section></main><footer class="wl-footer">Weli-Link Market · Assistant de recherche</footer>`;
  const script = `
const form=document.querySelector('#assistant-form');const result=document.querySelector('#assistant-result');const esc=(v)=>String(v??'').replace(/[&<>\"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[c]));const money=(v)=>new Intl.NumberFormat('fr-FR').format(v)+' F';const chatKey=()=>{let key=localStorage.getItem('wl_chat_key');if(!key){key=crypto.randomUUID();localStorage.setItem('wl_chat_key',key)}return key};const chatHeaders=()=>{const headers={'Content-Type':'application/json'};const token=localStorage.getItem('wl_token');if(token)headers.Authorization='Bearer '+token;return headers};const addBubble=(content,role)=>{const bubble=document.createElement('div');bubble.className='wl-bubble'+(role==='USER'?' user':'');bubble.textContent=content;result.appendChild(bubble);result.scrollTop=result.scrollHeight};const addProducts=(products)=>products.forEach(product=>{const card=document.createElement('div');card.className='wl-assistant-result';card.innerHTML='<strong>'+esc(product.title)+'</strong><p>'+esc(product.producer?.name||'Producteur local')+' · '+esc(product.location)+' · '+money(product.priceXaf)+'</p><span class="wl-status">'+esc(product.availability.state)+'</span>';result.appendChild(card)});async function loadHistory(){try{const response=await fetch('/api/assistant/history?conversationKey='+encodeURIComponent(chatKey()),{headers:chatHeaders()});const data=await response.json();if(!response.ok||!data.messages?.length)return;result.innerHTML='';data.messages.forEach(message=>addBubble(message.content,message.role));}catch(_error){/* Une nouvelle conversation peut commencer hors connexion. */}}form.addEventListener('submit',async(event)=>{event.preventDefault();const input=form.querySelector('input[name="message"]');const message=input.value.trim();if(!message)return;addBubble(message,'USER');input.value='';const loading=document.createElement('div');loading.className='wl-bubble';loading.textContent='Weli vérifie le catalogue…';result.appendChild(loading);try{const response=await fetch('/api/assistant/chat',{method:'POST',headers:chatHeaders(),body:JSON.stringify({message,conversationKey:chatKey()})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Weli est momentanément indisponible.');localStorage.setItem('wl_chat_key',data.conversationKey);loading.textContent=data.reply;addProducts(data.products||[])}catch(error){loading.className='wl-alert error';loading.textContent=error.message}finally{result.scrollTop=result.scrollHeight}});loadHistory();
`;
  return layout('Weli IA', content, script);
}

export function renderAssistantPage() {
  const content = `<main class="wl-page"><section class="wl-intro"><div><p class="wl-kicker">Assistant Weli</p><h1 class="wl-title">Décrivez votre besoin.</h1><p class="wl-subtitle">Weli garde le fil de cette conversation et consulte le catalogue réel avant de répondre.</p></div><div class="wl-intro-actions"><a class="wl-btn" href="/catalogue">Voir le catalogue</a><a class="wl-btn" href="/">Accueil</a></div></section><section class="wl-grid two"><article class="wl-card wl-ai"><h2>Weli est là</h2><p>Je peux chercher un produit, une quantité ou une région.</p><div id="assistant-result" class="wl-chat" aria-live="polite" aria-relevant="additions text"><div class="wl-bubble">Bonjour ! Que cherchez-vous aujourd’hui ?</div></div><form id="assistant-form" class="wl-form"><div class="wl-field"><label for="assistant-message">Votre question</label><input id="assistant-message" name="message" maxlength="500" required placeholder="Le miel est-il disponible à Yaoundé ?"></div><button id="assistant-submit" class="wl-btn accent" type="submit">Envoyer à Weli</button></form><div id="assistant-status" class="wl-live-note" role="status" aria-live="polite">La disponibilité affichée vient du catalogue Weli-Link.</div></article><article class="wl-card"><p class="wl-kicker">Une réponse fiable</p><h2>Pas de promesse inventée.</h2><p>Weli utilise le stock enregistré. Si la mise à jour est trop ancienne, il demande une reconfirmation au producteur au lieu d’annoncer une disponibilité incertaine.</p><div class="wl-alert" style="margin-top:15px">Le règlement et la livraison se font directement entre l’acheteur et le producteur.</div></article></section></main><footer class="wl-footer">Weli-Link Market · Assistant de recherche</footer>`;
  const script = `
const form=document.querySelector('#assistant-form');const result=document.querySelector('#assistant-result');const input=document.querySelector('#assistant-message');const submit=document.querySelector('#assistant-submit');const status=document.querySelector('#assistant-status');const esc=(v)=>String(v??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const money=(v)=>new Intl.NumberFormat('fr-FR').format(v)+' F';const chatKey=()=>{let key=localStorage.getItem('wl_chat_key');if(!key){key=crypto.randomUUID();localStorage.setItem('wl_chat_key',key)}return key};const chatHeaders=()=>{const headers={'Content-Type':'application/json'};const token=localStorage.getItem('wl_token');if(token)headers.Authorization='Bearer '+token;return headers};const scrollChat=()=>{result.scrollTop=result.scrollHeight};const addBubble=(content,role)=>{const bubble=document.createElement('div');bubble.className='wl-bubble'+(role==='USER'?' user':'');bubble.textContent=content;result.appendChild(bubble);scrollChat()};const addProducts=(products)=>products.forEach(product=>{const card=document.createElement('div');card.className='wl-assistant-result';card.innerHTML='<strong>'+esc(product.title)+'</strong><p>'+esc(product.producer?.name||'Producteur local')+' · '+esc(product.location)+' · '+money(product.priceXaf)+'</p><span class="wl-status">'+esc(product.availability.state)+'</span>';result.appendChild(card)});const setPending=(pending)=>{input.disabled=pending;submit.disabled=pending;submit.setAttribute('aria-busy',String(pending));submit.textContent=pending?'Weli recherche…':'Envoyer à Weli';status.textContent=pending?'Weli vérifie le catalogue réel…':'La disponibilité affichée vient du catalogue Weli-Link.'};async function loadHistory(){try{const response=await fetch('/api/assistant/history?conversationKey='+encodeURIComponent(chatKey()),{headers:chatHeaders()});const data=await response.json();if(!response.ok||!data.messages?.length)return;result.innerHTML='';data.messages.forEach(message=>addBubble(message.content,message.role));}catch(_error){/* Une nouvelle conversation peut commencer hors connexion. */}}async function sendMessage(messageOverride,renderUser=true){const message=typeof messageOverride==='string'?messageOverride:input.value.trim();if(!message||submit.disabled)return;if(renderUser)addBubble(message,'USER');input.value='';setPending(true);const loading=document.createElement('div');loading.className='wl-bubble';loading.textContent='Weli vérifie le catalogue…';result.appendChild(loading);scrollChat();try{const response=await fetch('/api/assistant/chat',{method:'POST',headers:chatHeaders(),body:JSON.stringify({message,conversationKey:chatKey()})});let data={};try{data=await response.json()}catch(_error){}if(!response.ok)throw new Error(data.error?.message||'Weli est momentanément indisponible.');localStorage.setItem('wl_chat_key',data.conversationKey);loading.textContent=data.reply;addProducts(data.products||[])}catch(error){loading.className='wl-alert error';loading.textContent=error instanceof Error?error.message:'Weli est momentanément indisponible.';status.textContent='La réponse n’a pas pu être reçue.';const retry=document.createElement('button');retry.type='button';retry.className='wl-btn';retry.textContent='Réessayer';retry.addEventListener('click',()=>{retry.remove();loading.remove();void sendMessage(message,false)});result.appendChild(retry)}finally{setPending(false);scrollChat()}}form.addEventListener('submit',(event)=>{event.preventDefault();void sendMessage()});loadHistory();
`;
  return layout('Weli IA', content, script);
}

export function renderNotificationsPage() {
  const content = `<main class="wl-page"><section class="wl-intro"><div><p class="wl-kicker">Suivi en direct</p><h1 class="wl-title">Vos notifications.</h1><p class="wl-subtitle">Retrouvez ici les réponses des producteurs, les confirmations de commandes et les mises à jour de stock.</p></div><div class="wl-intro-actions"><a class="wl-btn" href="/">Accueil</a><button class="wl-btn danger" data-logout>Se déconnecter</button></div></section><section class="wl-card"><div id="notification-list" class="wl-list"><div class="wl-empty">Chargement de vos notifications…</div></div></section></main><footer class="wl-footer">Weli-Link Market · Notifications</footer>`;
  const script = `${protectedGuard}
const list=document.querySelector('#notification-list');
const notificationDate=(value)=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
async function loadNotifications(){
  try{
    const response=await fetch('/api/notifications',{headers:{Authorization:'Bearer '+token}});
    const data=await response.json();
    if(!response.ok)throw new Error(data.error?.message||'Impossible de charger les notifications.');
    list.innerHTML=data.notifications.length?data.notifications.map((notification)=>'<div class="wl-row"><div class="wl-row-main"><strong>'+wlEscape(notification.title)+'</strong><span>'+wlEscape(notification.body)+' · '+notificationDate(notification.createdAt)+'</span></div><div class="wl-row-actions">'+(notification.readAt?'<span class="wl-pill">Lue</span>':'<button class="wl-btn accent" data-read="'+notification.id+'">Marquer comme lue</button>')+'</div></div>').join(''):'<div class="wl-empty">Vous n’avez pas encore de notification.</div>';
    document.querySelectorAll('[data-read]').forEach((button)=>button.addEventListener('click',async()=>{await fetch('/api/notifications/'+button.dataset.read+'/read',{method:'PATCH',headers:{Authorization:'Bearer '+token}});await loadNotifications();await wlRefreshNotifications()}));
  }catch(error){list.innerHTML='<div class="wl-alert error">'+wlEscape(error.message)+'</div>'}
}
loadNotifications();window.setInterval(loadNotifications,20000);
`;
  return layout('Notifications', content, script);
}

export function homeScript() {
  return `
const go=(path)=>{window.location.href=path};
const homeRolePath={BUYER:'/acheteur',PRODUCER:'/producteur',ADMIN:'/admin'};
const homeEscape=(value)=>String(value??'').replace(/[&<>\"']/g,(character)=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[character]));
const homeMoney=(value)=>new Intl.NumberFormat('fr-FR').format(value)+' F';
const clearSession=()=>{localStorage.removeItem('wl_token');localStorage.removeItem('wl_user');};
const homeChatKey=()=>{let key=localStorage.getItem('wl_chat_key');if(!key){key=crypto.randomUUID();localStorage.setItem('wl_chat_key',key)}return key};
const homeChatHeaders=()=>{const headers={'Content-Type':'application/json'};const token=localStorage.getItem('wl_token');if(token)headers.Authorization='Bearer '+token;return headers};
const renderGuestActions=()=>{const actions=document.querySelector('.h-actions');if(!actions)return;actions.innerHTML='<button class="h-btn h-btn-outline" type="button">Se connecter</button><button class="h-btn h-btn-primary" type="button">Créer un compte</button>';actions.children[0].onclick=()=>go('/connexion');actions.children[1].onclick=()=>go('/inscription')};
const renderMemberActions=(user)=>{const actions=document.querySelector('.h-actions');if(!actions)return;actions.innerHTML='<button class="h-btn h-btn-outline" type="button">Mon espace</button><button class="h-btn h-btn-primary" type="button">Notifications</button><button class="h-btn h-btn-outline" type="button">Quitter</button>';actions.children[0].onclick=()=>go(homeRolePath[user.role]||'/');actions.children[1].onclick=()=>go('/notifications');actions.children[2].onclick=()=>{clearSession();renderGuestActions()}};
document.querySelectorAll('.h-navlinks span').forEach((el)=>{const text=el.textContent.trim();if(text==='Catalogue')el.onclick=()=>go('/catalogue');if(text==='Aide')el.onclick=()=>go('/assistant')});
const searchButton=document.querySelector('.h-search button');if(searchButton)searchButton.onclick=()=>go('/catalogue');
document.querySelectorAll('.h-hero-actions button').forEach((button,index)=>button.onclick=()=>go(index===0?'/assistant':'/connexion?next=/producteur'));
document.querySelectorAll('.h-chat-card button,.h-ai-copy button').forEach((button)=>button.onclick=()=>go('/assistant'));
document.querySelectorAll('.h-products .h-price button').forEach((button)=>button.onclick=()=>go('/catalogue'));
document.querySelectorAll('.h-producer button').forEach((button)=>button.onclick=()=>go('/connexion?next=/producteur'));
async function validateHomeSession(){
  const token=localStorage.getItem('wl_token');if(!token){renderGuestActions();return;}
  try{const response=await fetch('/api/me',{headers:{Authorization:'Bearer '+token}});if(!response.ok)throw new Error('expired');const data=await response.json();localStorage.setItem('wl_user',JSON.stringify(data.user));renderMemberActions(data.user)}catch(_error){clearSession();renderGuestActions()}
}
async function hydrateHomeCatalog(){try{const response=await fetch('/api/products');if(!response.ok)return;const data=await response.json();const products=(data.products||[]).slice(0,4);const list=document.querySelector('.h-products');if(!list||!products.length)return;list.innerHTML=products.map((product)=>'<div class="h-product"><div class="h-photo">'+homeEscape(product.title)+'</div><div class="h-product-body"><strong>'+homeEscape(product.title)+'</strong><span>'+homeEscape(product.location)+' · '+product.availability.availableQuantity+' '+homeEscape(product.unit)+'</span><span class="h-human-seller">Publié par '+homeEscape(product.producer?.name||'un producteur local')+'</span><div class="h-price"><b>'+homeMoney(product.priceXaf)+'</b><button type="button">Voir</button></div></div></div>').join('');list.querySelectorAll('button').forEach((button)=>button.onclick=()=>go('/catalogue'))}catch(_error){/* Le catalogue de démonstration reste affiché si l’API est indisponible. */}}
async function askHomeWeli(messageOverride,renderUser=true){
  const input=document.querySelector('.h-ai-input input');const messages=document.querySelector('.h-msgs');const send=document.querySelector('.h-ai-input button');if(!input||!messages||!send)return;const message=typeof messageOverride==='string'?messageOverride:input.value.trim();if(!message||send.disabled)return;
  if(renderUser){const userBubble=document.createElement('div');userBubble.className='h-msg user';userBubble.textContent=message;messages.appendChild(userBubble)}
  input.value='';input.disabled=true;send.disabled=true;send.setAttribute('aria-busy','true');
  const loading=document.createElement('div');loading.className='h-msg ai';loading.textContent='Weli regarde les offres disponibles…';messages.appendChild(loading);messages.scrollTop=messages.scrollHeight;
  try{const response=await fetch('/api/assistant/chat',{method:'POST',headers:homeChatHeaders(),body:JSON.stringify({message,conversationKey:homeChatKey()})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Weli est momentanément indisponible.');localStorage.setItem('wl_chat_key',data.conversationKey);loading.textContent=data.reply;(data.products||[]).slice(0,3).forEach((product)=>{const card=document.createElement('div');card.className='h-reco';card.innerHTML='<strong>'+homeEscape(product.title)+'</strong><div class="h-reco-line"><span>'+homeEscape(product.producer?.name||'Producteur local')+' · '+homeEscape(product.location)+'</span><b>'+homeMoney(product.priceXaf)+'</b></div><div class="h-reco-line"><span>'+product.availability.availableQuantity+' '+homeEscape(product.unit)+' disponibles</span><span>Voir la fiche →</span></div>';messages.appendChild(card)});}
  catch(error){loading.textContent=error instanceof Error?error.message:'Weli est momentanément indisponible.';loading.className='h-msg ai h-chat-error';const retry=document.createElement('button');retry.type='button';retry.className='h-btn h-btn-outline h-chat-retry';retry.textContent='Réessayer';retry.addEventListener('click',()=>{retry.remove();loading.remove();askHomeWeli(message,false)});messages.appendChild(retry)}
  finally{input.disabled=false;send.disabled=false;send.removeAttribute('aria-busy');messages.scrollTop=messages.scrollHeight}
}
const homeChatButton=document.querySelector('.h-ai-input button');const homeChatInput=document.querySelector('.h-ai-input input');if(homeChatButton){homeChatButton.onclick=()=>askHomeWeli();homeChatInput?.addEventListener('keydown',(event)=>{if(event.key==='Enter'){event.preventDefault();askHomeWeli()}})}
  async function hydrateHomeShowcase(){
    const anchor=document.querySelector('.h-products-section');
    if(!anchor||document.querySelector('.h-showcase-section'))return;
    try{
      const response=await fetch('/api/showcase-products');
      if(!response.ok)return;
      const data=await response.json();
      const products=(data.products||[]).filter((product)=>typeof product?.imageUrl==='string'&&product.imageUrl.startsWith('/assets/products/')).slice(0,6);
      if(!products.length)return;
      const section=document.createElement('section');section.className='h-wrap h-section h-showcase-section';
      const heading=document.createElement('div');heading.className='h-section-head';
      const headingCopy=document.createElement('div');const kicker=document.createElement('p');kicker.className='h-kicker';kicker.textContent='Produits du terroir';const title=document.createElement('h2');title.textContent='Les saveurs locales à découvrir.';headingCopy.append(kicker,title);
      const description=document.createElement('p');description.textContent='Ces produits sont mis en avant. Le producteur ajoute lui-même le prix et la disponibilité lorsqu’il publie une offre.';heading.append(headingCopy,description);
      const grid=document.createElement('div');grid.className='h-showcase-grid';
      products.forEach((product)=>{const card=document.createElement('article');card.className='h-showcase-card';const media=document.createElement('div');media.className='h-showcase-media';const image=document.createElement('img');image.src=product.imageUrl;image.alt=typeof product.alt==='string'?product.alt:'Produit local '+String(product.title||'');image.loading='lazy';image.decoding='async';const tag=document.createElement('span');tag.className='h-showcase-tag';tag.textContent='Produit local';media.append(image,tag);const copy=document.createElement('div');copy.className='h-showcase-copy';const name=document.createElement('strong');name.textContent=String(product.title||'Produit local');const category=document.createElement('span');category.textContent=String(product.category||'Produit du terroir');const link=document.createElement('a');link.href='/catalogue';link.textContent='Voir le catalogue →';copy.append(name,category,link);card.append(media,copy);grid.append(card)});
      section.append(heading,grid);anchor.insertAdjacentElement('afterend',section);
    }catch(_error){/* Le reste de l’accueil demeure disponible si la sélection ne peut pas être chargée. */}
  }
  validateHomeSession();hydrateHomeCatalog();hydrateHomeShowcase();
`;
}
